"""Private local storage helpers for submitted answer recordings."""

from datetime import datetime, timedelta, timezone
import logging
from pathlib import Path
import re


logger = logging.getLogger(__name__)
AUDIO_DIRECTORY = Path(__file__).resolve().parents[2] / "uploads" / "audio"
SAFE_AUDIO_NAME = re.compile(r"^[0-9a-f]{32}\.(webm|ogg|mp4|wav|mp3)$")


def get_audio_directory() -> Path:
    AUDIO_DIRECTORY.mkdir(parents=True, exist_ok=True)
    return AUDIO_DIRECTORY


def remove_audio_file(filename: str) -> None:
    """Remove only a recording filename generated by this service."""
    if not SAFE_AUDIO_NAME.fullmatch(filename or ""):
        logger.warning("Skipped removal of an invalid stored audio filename")
        return
    try:
        (AUDIO_DIRECTORY / filename).unlink(missing_ok=True)
    except OSError:
        logger.warning("Could not remove stored audio recording %s", filename)


def cleanup_expired_audio(retention_days: int = 30) -> int:
    """Remove aged recording files while retaining transcript/analysis records."""
    if not AUDIO_DIRECTORY.exists():
        return 0
    cutoff = datetime.now(timezone.utc) - timedelta(days=retention_days)
    removed = 0
    for item in AUDIO_DIRECTORY.iterdir():
        try:
            if item.is_file() and datetime.fromtimestamp(item.stat().st_mtime, timezone.utc) < cutoff:
                item.unlink()
                removed += 1
        except OSError:
            logger.warning("Could not remove expired audio recording %s", item.name)
    return removed
